import { useState, useEffect, useCallback } from 'react';
import { RoomMemberService } from '@/services/room-member.service';
import { RoomMember, RoomMemberPayload } from '@/types/room-member';
import { client, DB_ID, COLLECTIONS } from '@/lib/appwrite';
import { useSession } from './useSession';

export function useRoomMembers(roomId: string) {
    const { session, isAuthenticated } = useSession(); // Source of Truth Rule #3 for Joining
    const [members, setMembers] = useState<RoomMember[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchMembers = useCallback(async () => {
        if (!roomId) return;
        setLoading(true);
        try {
            const response = await RoomMemberService.list(roomId);
            setMembers(response.documents);
        } catch (err: any) {
            console.error('Fetch members failed:', err);
            setError(err.message || 'Failed to list members');
        } finally {
            setLoading(false);
        }
    }, [roomId]);

    useEffect(() => {
        fetchMembers();

        const unsubscribe = client.subscribe(
            `databases.${DB_ID}.collections.${COLLECTIONS.ROOM_MEMBERS}.documents`,
            (response) => {
                // Filter for this room
                const payload = response.payload as RoomMember;
                if (payload.room !== roomId) return;

                if (response.events.includes('databases.*.collections.*.documents.*.create')) {
                    // Check if active
                    if (payload.isActive) setMembers(prev => [...prev, payload]);
                } else if (response.events.includes('databases.*.collections.*.documents.*.update')) {
                    if (payload.isActive) {
                        setMembers(prev => {
                            const exists = prev.find(m => m.$id === payload.$id);
                            return exists ? prev.map(m => m.$id === payload.$id ? payload : m) : [...prev, payload];
                        });
                    } else {
                        // Removed/Kicked
                        setMembers(prev => prev.filter(m => m.$id !== payload.$id));
                    }
                } else if (response.events.includes('databases.*.collections.*.documents.*.delete')) {
                    setMembers(prev => prev.filter(m => m.$id !== payload.$id));
                }
            }
        );

        return () => {
            unsubscribe();
        };
    }, [fetchMembers, roomId]);

    const addMember = async (payload: RoomMemberPayload) => {
        // Enforce active session for joining
        if (!isAuthenticated || !session) {
            throw new Error("Active session required to join room");
        }

        try {
            await RoomMemberService.add(payload);
        } catch (err: any) {
            console.error('Add member failed:', err);
            throw err;
        }
    };

    // Additional Logic: Creator Actions
    // Kick Member
    const kickMember = async (memberId: string) => {
        // Should verify isCreator here or in UI? 
        // Service handles DB call, but we can check local permission first for Fail Fast.
        // For now, let service/Appwrite security rules handle deep permission, but we assume UI hides button.
        try {
            await RoomMemberService.kick(memberId);
        } catch (err: any) {
            throw err;
        }
    };

    return {
        members,
        loading,
        error,
        addMember,
        kickMember
    };
}
